    by_vid = {}
    lyrics_dir = 'cache/lyrics'
    if not os.path.isdir(lyrics_dir):
        return []
    for fname in os.listdir(lyrics_dir):
        key = _cache_key_from_filename(fname)
        if key is None:
            continue
        try:
            entry = json.load(open(os.path.join(lyrics_dir, fname), 'r', encoding='utf-8'))
            data = entry.get('data')
            if _tier(data) >= 2:
                continue
            parts = key.split(':')
            is_fast = parts[-1] == 'fast'
            lang = parts[-2] if is_fast else parts[-1]
            vid = ':'.join(parts[:-2] if is_fast else parts[:-1])
            if not vid or not lang:
                continue
            last = _rerace_last_attempt.get((vid, lang), 0)
            if now - last < cooldown:
                continue
            cand = (key, vid, lang, entry.get('ts', ''), _tier(data))
            cur = by_vid.get(vid)
            # prefer the full key over the :fast sibling of the same video
            if cur is None or cur[0].endswith(':fast'):
                by_vid[vid] = cand
        except Exception:
            continue
    out = sorted(by_vid.values(), key=lambda x: x[3])
    return out[:limit]


def _translate_upgrade_in_place(up, lang):
    """Fill missing translated rows on an upgrade payload (fast Google pass,
    same as the network path below). Index-aligned on text-bearing lines so
    textless/gap rows never shift later translations. Never raises."""
    if not lang or not up or not up.get('lyrics'):
        return
    texts = [l['text'] for l in up['lyrics'] if l.get('text')]
    try:
        translations = google_translate_fast(texts, lang)
        ti = 0
        for l in up['lyrics']:
            if not l.get('text'):
                continue
            if ti < len(translations) and translations[ti] and not l.get('translated'):
                l['translated'] = translations[ti]
            ti += 1
    except Exception as e:
        print(f"  [RERACE] inline translation skipped: {e}")


def _rerace_video(video_id, lang, old_data):
    """Try to find a strictly-better word-by-word result. Returns the
    upgraded payload or None. Never raises to the caller."""
    title = old_data.get('song') or ''
    artist = old_data.get('artist') or ''
    if not title and not artist:
        return None
    queries = get_search_queries(title, artist, '', '')
    if not queries:
        return None
    duration = int(old_data.get('duration', 0) or 0)
    album = old_data.get('album', '') or ''
    node = pick_node()

    # Saved probe snapshot first: reuse every provider without re-fetching.
    # Strictly-better tier wins outright; otherwise a wbw snapshot with the
    # same lines is grafted onto the cached lyrics.
    try:
        _snap = load_snapshot(video_id)
    except Exception:
        _snap = None
    saved = (_snap or {}).get('candidates') if _snap else None
    # Outcome tags: providers that missed/errored/skipped in the latest
    # snapshot are not re-tried on the network leg below.
    _skip = set()
    try:
        for _p, _o in ((_snap or {}).get('outcomes') or {}).items():
            if isinstance(_o, dict) and _o.get('status') in ('missed', 'error', 'skipped'):
                _skip.add(_p)
    except Exception:
        pass
    if _skip:
        print(f"  [RERACE] {video_id} skipping known-miss providers: {sorted(_skip)}")
    if saved:
        for c in saved:
            d = (c or {}).get('data') or {}
            if not d.get('lyrics'):
                continue
            if _tier(d) > _tier(old_data):
                up = copy.deepcopy(d)
                up['song'] = old_data.get('song', '') or title
                up['artist'] = old_data.get('artist', '') or artist
                _translate_upgrade_in_place(up, lang)
                sanitize_lyrics_parts(up['lyrics'])
                print(f"  [RERACE] {video_id} upgrade from saved {c.get('provider')} tier {_tier(old_data)}->{_tier(up)}")
                return up
        if _tier(old_data) < 2:
            for c in saved:
                d = (c or {}).get('data') or {}
                if _wbw_line_count(d) == 0:
                    continue
                working = copy.deepcopy(old_data.get('lyrics') or [])
                if working and graft_wbw_parts(working, d.get('lyrics') or []):
                    up = copy.deepcopy(old_data)
                    up['lyrics'] = working
                    up['synced'] = True
                    up['wordSynced'] = True
                    up['graftedFrom'] = c.get('provider', '')
                    _translate_upgrade_in_place(up, lang)
                    sanitize_lyrics_parts(up['lyrics'])
                    print(f"  [RERACE] {video_id} grafted wbw from saved {c.get('provider')}")
                    return up
    found = []
    _found_lock = threading.Lock()

    def _take(cand):
        if cand:
            sanitize_lyrics_parts(cand['lyrics'])
            with _found_lock:
                found.append(cand)

    _rerace_groups = []
    _MISS_TO_SRC = {'bLyrics': 'ttml', 'QQ': 'qq', 'KuGou': 'kugou', 'BiniLyrics': 'binimum'}
    for name, sources in (('boidu', ('ttml', 'qq', 'kugou')), ('binimum', ('binimum',))):
        sources = tuple(s for s in sources
                        if not any(_MISS_TO_SRC.get(m) == s for m in _skip))
        if not sources:
            continue

        def _direct_leg(_sources=sources, _name=name):
            try:
                cand = fetch_direct_best(queries, album, duration, sources=_sources, via_node=node)
                if cand:
                    _take(cand)
            except Exception as e:
                print(f"  [RERACE] {_name} worker error: {e}")
        _rerace_groups.append(_direct_leg)

    _CUBEY_INNERS = ('Musixmatch', 'QQ', 'bLyrics', 'BiniLyrics', 'NetEase', 'KuGou')
    if not all(f'Cubey/{i}' in _skip for i in _CUBEY_INNERS):
        def _cubey_leg():
            try:
                cubey = _race_cubey(queries, video_id, duration, None)
                if cubey:
                    _take(cubey)
            except Exception as e:
                print(f"  [RERACE] Cubey error: {e}")
        _rerace_groups.append(_cubey_leg)
    else:
        print(f"  [RERACE] {video_id} Cubey skipped (all inners missed in snapshot)")

    # All legs concurrently; wall time is the slowest leg, not the sum.
    if _rerace_groups:
        with concurrent.futures.ThreadPoolExecutor(max_workers=len(_rerace_groups),
                                                   thread_name_prefix='rerace') as _rexec:
            for _f in concurrent.futures.as_completed(
                    [_rexec.submit(_g) for _g in _rerace_groups]):
                try:
                    _f.result()
                except Exception as e:
                    print(f"  [RERACE] leg error: {e}")

    best = None
    for cand in found:
        if best is None or _lyrics_score(cand) > _lyrics_score(best):
            best = cand

    if not best:
        return None
    if _tier(best) <= _tier(old_data):
        return None
    if not best.get('lyrics'):
        return None

    best['song'] = old_data.get('song', '') or title
    best['artist'] = old_data.get('artist', '') or artist
    _translate_upgrade_in_place(best, lang)
    sanitize_lyrics_parts(best['lyrics'])
    return best


def rerace_pass():
    """One cooldown-gated pass over the cache. Logs every upgrade so the
    dashboard timeline shows old -> new without re-reading the file."""
    try:
        candidates = _cache_candidates(_RERACE_BATCH, _RERACE_COOLDOWN)
    except Exception as e:
        print(f"  [RERACE] candidate scan error: {e}")
        return
    if not candidates:
        return
    print(f"  [RERACE] pass: {len(candidates)} candidate(s)")
    for key, vid, lang, _ts, old_tier in candidates:
        old_data = get_cached(key)
        if old_data is None:
            continue
        try:
            upgraded = _rerace_video(vid, lang, old_data)
            with _rerace_lock:
                _rerace_last_attempt[(vid, lang)] = time_module.time()
            if not upgraded:
                continue
            full_key = f"{vid}:{lang}"
            fast_key = f"{full_key}:fast"
            new_tier = _tier(upgraded)
            set_cached(full_key, upgraded)
            if get_cached(fast_key) is not None or key.endswith(':fast'):
                set_cached(fast_key, upgraded)
            print(f"  [RERACE] [OK] {vid} upgraded tier {old_tier}->{new_tier} "
                  f"source={upgraded.get('source')} lines={len(upgraded.get('lyrics', []))}")
        except Exception as e:
            print(f"  [RERACE] pass item error {vid}: {e}")
    print("  [RERACE] pass done")


def _rerace_loop():
    while True:
        time_module.sleep(_RERACE_INTERVAL)
        try:
            rerace_pass()
        except Exception as e:
            print(f"  [RERACE] pass error: {e}")


def start_rerace():
    threading.Thread(target=_rerace_loop, args=(), daemon=True).start()
    print(f"  [RERACE] background re-race loop started (interval={_RERACE_INTERVAL}s, batch={_RERACE_BATCH})")

