        _rebase_job['job_id'] = str(int(time_module.time() * 1000))
        _rebase_job['total'] = 0
        _rebase_job['done'] = 0
        _rebase_job['upgraded'] = 0
        _rebase_job['same'] = 0
        _rebase_job['failed'] = 0
        _rebase_job['error'] = 0
        _rebase_job['already'] = 0
        _rebase_job['current'] = None
        _rebase_job['results'] = []
        _rebase_cancel.clear()

    def _run():
        try:
            if mode == 'unlyriced':
                _run_rebase_unlyriced(target_vid)
