/* ---- log list ---- */
.log-list { display:flex; flex-direction:column; gap:2px; max-height: 70vh; overflow: auto; }
.log-row { display:flex; gap:10px; padding:6px 10px; border-left: 3px solid var(--log-c, rgb(var(--mdui-color-outline-variant))); border-radius: var(--mdui-shape-corner-extra-small); font-family: Consolas, Menlo, monospace; font-size:13px; line-height: 1.6; animation: login .22s; white-space: pre-wrap; word-break: break-word; }
.log-row:hover { background: rgba(var(--mdui-color-surface-variant),.35); }
.log-time { color: rgb(var(--mdui-color-on-surface-variant)); flex:0 0 auto; }
.log-msg { flex:1; }
.log-row.lv-info { --log-c: rgb(var(--mdui-color-outline-variant)); }
.log-row.lv-warn { --log-c: rgb(234,179,8); }
.log-row.lv-error { --log-c: rgb(var(--mdui-color-error)); }
.log-row.lv-debug { --log-c: rgb(var(--mdui-color-outline)); }
@keyframes login { from { opacity:0; transform: translateY(-5px); } to { opacity:1; transform:none; } }

/* ---- cache / request / node / file lists ---- */
.list-grid { display:flex; flex-direction:column; gap:6px; max-height: 60vh; overflow: auto; }
.list-row { display:grid; gap:10px; align-items:center; padding:10px 16px; border-radius: var(--mdui-shape-corner-extra-small); background: rgba(var(--mdui-color-surface),.55); font-size: 13.5px; }
.list-row:hover { background: rgba(var(--mdui-color-surface-variant),.35); }
.list-row.rq { grid-template-columns: 1fr 80px 80px 100px 70px; }
.list-row.cache { grid-template-columns: 1fr 70px 60px 50px 70px 40px 36px 36px; }
.list-row.file { grid-template-columns: 1fr 90px 160px 44px; }
.list-row.node { grid-template-columns: 1fr 120px 120px 90px 36px; }
.list-row.jwt { grid-template-columns: 1fr 90px 80px 80px 80px 110px 100px 36px; }
.list-head { font-size:11px; color: rgb(var(--mdui-color-on-surface-variant)); font-weight:500; padding:0 16px 6px; }
.list-head.lh-rq { grid-template-columns: 1fr 80px 80px 100px 70px; display:grid; gap:10px; }
.list-head.lh-cache { grid-template-columns: 1fr 70px 60px 50px 70px 40px 36px 36px; display:grid; gap:10px; }
.list-head.lh-file { grid-template-columns: 1fr 90px 160px 44px; display:grid; gap:10px; }
.list-head.lh-node { grid-template-columns: 1fr 120px 120px 90px 36px; display:grid; gap:10px; }
.list-head.lh-jwt { grid-template-columns: 1fr 90px 80px 80px 80px 110px 100px 36px; display:grid; gap:10px; }

/* ---- pre code block ---- */
.code-block { position:relative; }
.code-block pre { margin:0; padding:12px 14px; border-radius: var(--mdui-shape-corner-extra-small); background: rgb(var(--mdui-color-surface-container-highest)); color: rgb(var(--mdui-color-on-surface)); font-size:12.5px; overflow-x:auto; white-space: pre-wrap; word-break: break-all; }
.code-block .copy-btn { position:absolute; top:6px; right:6px; }

/* ---- misc ---- */
.spacer { flex:1; }
.truncate { overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }
.mono { font-family: Consolas, Menlo, monospace; }

/* ---- update dialog ---- */
#updateDialogBody { display:flex; flex-direction:column; gap:12px; }
#updateStageLine { font-size:13.5px; }
#pingStatus { display:flex; align-items:center; gap:8px; font-size:12.5px; color: rgb(var(--mdui-color-on-surface-variant)); }

/* ---- stagger ---- */
.stagger > * { animation: rise .28s var(--mdui-motion-easing-emphasized-decelerate) both; }
.stagger > *:nth-child(1) { animation-delay: 0ms; }
.stagger > *:nth-child(2) { animation-delay: 40ms; }
.stagger > *:nth-child(3) { animation-delay: 80ms; }
.stagger > *:nth-child(4) { animation-delay: 120ms; }
.stagger > *:nth-child(5) { animation-delay: 160ms; }
.stagger > *:nth-child(6) { animation-delay: 200ms; }

/* ---- responsive ---- */
@media (max-width: 599.98px) {
  .stat-grid { grid-template-columns: 1fr 1fr; }
  .list-row.cache { grid-template-columns: 1fr 60px 36px 36px; }
  .list-head.lh-cache { grid-template-columns: 1fr 60px 36px 36px; }
  .list-row.cache > :nth-child(2),
  .list-row.cache > :nth-child(3),
  .list-row.cache > :nth-child(5),
  .list-row.cache > :nth-child(6),
  .list-head.lh-cache > :nth-child(2),
  .list-head.lh-cache > :nth-child(3),
  .list-head.lh-cache > :nth-child(5),
  .list-head.lh-cache > :nth-child(6) { display:none; }
}

@media (prefers-reduced-motion: reduce) {
  .page.active, .log-row, .stagger > *, .stat-value.pulse, .live-dot::after, .skeleton, .list-row { animation: none !important; transition: none !important; }
}

/* ---- lyrics preview (braccato) ---- */
#prev-lyrics { scrollbar-width: thin; }

/* ---- rebase ---- */
.rebase-list { display:flex; flex-direction:column; gap:4px; max-height: 40vh; overflow-y: auto; }
.rebase-row { display:block; padding: 6px 12px; border-radius: var(--mdui-shape-corner-extra-small); border-left: 4px solid; font-size: 12.5px; }
.rb-upgraded { background-color: rgba(46,125,50,.14); border-left-color: rgb(46,125,50); color: rgb(var(--mdui-color-on-surface)); }
.rb-upgraded:hover { background-color: rgba(46,125,50,.22); }
.rb-same { background-color: rgba(234,179,8,.14); border-left-color: rgb(182,130,6); color: rgb(var(--mdui-color-on-surface)); }
.rb-same:hover { background-color: rgba(234,179,8,.22); }
.rb-failed, .rb-error { background-color: rgba(198,40,40,.13); border-left-color: rgb(198,40,40); color: rgb(var(--mdui-color-on-surface)); }
.rb-failed:hover, .rb-error:hover { background-color: rgba(198,40,40,.22); }
.rb-already { background-color: rgba(var(--mdui-color-on-surface-variant),.12); border-left-color: rgb(var(--mdui-color-on-surface-variant)); color: rgb(var(--mdui-color-on-surface)); }
.rb-already:hover { background-color: rgba(var(--mdui-color-on-surface-variant),.22); }
html.mdui-theme-dark .rb-upgraded { background-color: rgba(102,187,106,.16); border-left-color: rgb(102,187,106); }
html.mdui-theme-dark .rb-same { background-color: rgba(255,213,79,.14); border-left-color: rgb(255,213,79); }
html.mdui-theme-dark .rb-failed, html.mdui-theme-dark .rb-error { background-color: rgba(242,139,135,.15); border-left-color: rgb(242,139,135); }

/* ---- refetch / playlist sync ---- */
.refetch-inputs, .plsync-inputs { display:grid; gap:12px; margin-bottom:8px; }
.refetch-inputs { grid-template-columns: 1fr 120px; }
.plsync-inputs { grid-template-columns: 1fr 120px; }
.refetch-meta { font-size:12.5px; color: rgb(var(--mdui-color-on-surface-variant)); margin-bottom:10px; }
.probe-row { display:flex; align-items:center; gap:10px; flex-wrap:wrap; }
.probe-row .probe-name { font-weight:600; min-width:110px; }
.probe-row .probe-source { font-size:12px; opacity:.8; }
.probe-row .probe-actions { margin-left:auto; display:flex; gap:8px; }
@media (max-width: 899.98px) {
  .refetch-inputs { grid-template-columns: 1fr 100px; }
  .plsync-inputs { grid-template-columns: 1fr 100px; }
}
.rename-tag { font-size:11.5px; color: rgb(var(--mdui-color-primary)); white-space:nowrap; }

/* ---- live probe race log ---- */
.probe-live { font-family: ui-monospace, Consolas, monospace; font-size:12px; line-height:1.7;
  background: rgba(0,0,0,.45); border-radius:8px; padding:8px 12px; margin-bottom:10px;
  max-height:180px; overflow-y:auto; display:none; }
.probe-live.has-lines { display:block; }
/* Animated per-provider rows: flex row, continuous spinner while running,
   smooth elapsed ticker, determinate pill + retry when landed. */
.probe-live-row { display:flex; align-items:center; gap:8px; padding:2px 0;
  animation: probe-row-in .18s ease-out; }
@keyframes probe-row-in { from { opacity:0; transform:translateY(-3px); } to { opacity:1; transform:none; } }
.probe-live-row .mono { font-family: inherit; }
.probe-live .pl-ok { color: rgb(102,187,106); }
.probe-live .pl-miss { color: rgb(var(--mdui-color-on-surface-variant)); }
.probe-live .pl-fail { color: rgb(242,139,135); }
.probe-live .pl-run { color: rgb(144,202,249); }
html.mdui-theme-light .probe-live { background: rgba(0,0,0,.06); }
html.mdui-theme-light .probe-live .pl-ok { color: rgb(46,125,50); }
html.mdui-theme-light .probe-live .pl-fail { color: rgb(198,40,40); }
html.mdui-theme-light .probe-live .pl-run { color: rgb(21,101,192); }

/* ---- bulk refetch options ---- */
.bulk-opts { display:grid; grid-template-columns: auto auto 110px 130px 130px auto; gap:16px; align-items:end; margin-bottom:4px; }
.bulk-opt { display:flex; flex-direction:column; gap:6px; }
.bulk-label { font-size:11.5px; color: rgb(var(--mdui-color-on-surface-variant)); font-weight:500; }
.bulk-opt mdui-switch { margin-bottom:14px; }
@media (max-width: 899.98px) {
  .bulk-opts { grid-template-columns: 1fr 1fr; }
}

(() => {
  const API = async (path, opts = {}) => {
    const r = await fetch(path, opts);
    if (!r.ok) throw new Error(`HTTP ${r.status}`);
    return r;
  };
  const json = async (path, opts) => (await API(path, opts)).json();

  let activePage = 'overview';
  let eventSource = null;
  let logPaused = false;
  const logLines = [];
  const LOG_MAX = 300;
  // Push cadence for the SSE heartbeat (?interval=); page data refreshes
  // server-driven on each ping instead of client-side polling.
  const SSE_INTERVAL = 15;

  const $ = s => document.querySelector(s);
  const $$ = s => [...document.querySelectorAll(s)];
  const el = (tag, attrs, ...kids) => {
    const e = document.createElement(tag);
    if (attrs) Object.entries(attrs).forEach(([k, v]) => {
      if (k === 'class') e.className = v;
      else if (k === 'html') e.innerHTML = v;
      else e.setAttribute(k, v);
    });
    kids.forEach(c => { if (c != null) e.appendChild(typeof c === 'string' ? document.createTextNode(c) : c); });
    return e;
  };
  const esc = s => { const d = document.createElement('div'); d.textContent = s; return d.innerHTML; };
  const fmt = n => n == null ? '--' : String(n);
  const shortSha = s => s ? s.slice(0, 8) : '--';
  const ago = iso => {
    if (!iso) return '--';
    let d = Date.now() - new Date(iso).getTime();
    if (!Number.isFinite(d)) return '--';
    if (d < 0) d = 0;
    if (d < 60000) return Math.round(d/1000)+'s';
    if (d < 3600000) return Math.round(d/60000)+'m';
    if (d < 86400000) return Math.round(d/3600000)+'h';
    return Math.round(d/86400000)+'d';
  };

  /* ---- theme ---- */
  const THEMES = ['auto', 'dark', 'light'];
  let themeIdx = parseInt(localStorage.getItem('ymtu-theme-idx'), 10);
  if (!Number.isFinite(themeIdx) || themeIdx < 0) themeIdx = 0;
  const applyTheme = () => {
    const t = THEMES[themeIdx];
    if (mdui.setTheme) mdui.setTheme(t);
    else { document.documentElement.classList.remove('mdui-theme-light','mdui-theme-dark','mdui-theme-auto'); document.documentElement.classList.add('mdui-theme-'+t); }
    const btn = $('#theme-btn');
    if (btn) btn.setAttribute('icon', t === 'light' ? 'light_mode' : t === 'dark' ? 'dark_mode' : 'brightness_auto');
  };

  /* ---- stat helpers ---- */
  let lastStat = {};
  const setVal = (id, v) => {
    const e = $(id);
    if (!e) return;
    if (e.textContent === v) return;
    e.textContent = v;
    e.classList.remove('pulse');
    void e.offsetWidth;
    e.classList.add('pulse');
  };

  /* ---- uptime (per-digit flip clock) ---- */
  let startIso = null;
  let uptimeClockBuilt = false;
  const flipUptimeDigit = (digit, ch) => {
    const old = digit.querySelector('.old');
    const nw = digit.querySelector('.new');
    if (!old || !nw || old.textContent === ch) return;
    nw.textContent = ch;
    digit.classList.add('flip');
    clearTimeout(digit._flipT);
    digit._flipT = setTimeout(() => {
      old.textContent = ch;
      digit.classList.remove('flip');
      nw.textContent = ch;
    }, 300);
  };
  const tickUptime = () => {
    if (!startIso) return;
    const s = Math.max(0, Math.floor((Date.now() - new Date(startIso).getTime()) / 1000));
    const h = Math.floor(s / 3600);
    const m = Math.floor((s % 3600) / 60);
    const sec = s % 60;
    const str = `${String(h).padStart(2,'0')}h ${String(m).padStart(2,'0')}m ${String(sec).padStart(2,'0')}s`;
    const root = $('#stat-uptime');
    if (!root) return;
    if (!uptimeClockBuilt) {
      root.innerHTML = '';
      [...str].forEach(ch => {
        if (/\d/.test(ch)) {
          const d = el('span', {class:'digit'});
          d.appendChild(el('span', {class:'old'}, ch));
          d.appendChild(el('span', {class:'new'}, ch));
          root.appendChild(d);
        } else {
          root.appendChild(el('span', {class:'up-char'}, ch));
        }
      });
      uptimeClockBuilt = true;
      return;
    }
    const digits = [...root.querySelectorAll('.digit')];
    let di = 0;
    [...str].forEach(ch => {
      if (/\d/.test(ch)) {
        const d = digits[di++];
        if (d) flipUptimeDigit(d, ch);
      }
    });
  };

  /* ---- overview ---- */
  const loadOverview = async () => {
    try {
      const info = await json('/api/admin/server_info');
      startIso = info.start_time;
      tickUptime();
      setVal('#stat-logs', fmt(info.structured_logs));
      setVal('#stat-req', fmt(info.recent_requests?.length));
      setVal('#stat-crash', fmt(info.crash_logs));
      setVal('#stat-lyrics', fmt(info.lyrics_count));
      const kv = $('#server-kv');
      if (kv) {
        kv.innerHTML = '';
        const pairs = [
          ['Instance', `<span class="mono">${esc(info.instance_id)}</span>`],
          ['Start time', esc(info.start_time)],
          ['Uptime', esc(info.uptime_human)],
          ['Recent requests', fmt(info.recent_requests?.length)],
          ['Log files', `${(info.log_files||[]).length} file(s)`],
        ];
        pairs.forEach(([k, v]) => {
          kv.appendChild(el('div', {class:'k'}, k));
          kv.appendChild(el('div', {class:'v mono', html: v}));
        });
      }
      const chip = $('#instance-chip');
      if (chip && info.instance_id) chip.innerHTML = `<mdui-icon name="memory"></mdui-icon> ${esc(info.instance_id.slice(0,8))}`;
      const rr = $('#recent-reqs');
      if (rr) {
        rr.innerHTML = '';
        const reqs = (info.recent_requests||[]).slice().reverse().slice(0,12);
        if (!reqs.length) rr.appendChild(el('div', {class:'list-row'}, 'No recent requests'));
        else {
          reqs.forEach(r => {
            rr.appendChild(el('div', {class:'list-row rq', style:'font-size:12px;'},
              el('span', {class:'truncate'}, r.v || ''),
              el('span', {}, r.mode || ''),
              el('span', {class:'mono'}, r.ip || ''),
              el('span', {class:'truncate mono'}, r.ts ? r.ts.replace('T',' ').slice(0,19) : ''),
              el('span', {class:'mono'}, r.id ? r.id.slice(0,6) : ''),
            ));
          });
        }
      }
    } catch (e) {
      console.warn('overview load failed', e);
    }
  };

  /* ---- logs ---- */
  const renderLogRow = entry => {
    const cls = `log-row lv-${entry.level||'info'}`;
    return el('div', {class: cls},
      el('span', {class:'log-time'}, entry.ts || ''),
      el('span', {class:'log-msg'}, entry.msg || ''),
    );
  };
  const connectSSE = () => {
    if (eventSource) return;
    eventSource = new EventSource(`/api/admin/events?interval=${SSE_INTERVAL}`);
    eventSource.addEventListener('snapshot', e => {
      try {
        const data = JSON.parse(e.data);
        const container = $('#log-list');
        if (!container) return;
        container.innerHTML = '';
        (data.logs||[]).forEach(entry => {
          const row = renderLogRow(entry);
          container.appendChild(row);
          logLines.push(row);
        });
        while (logLines.length > LOG_MAX) {
          const old = logLines.shift();
          if (old.parentNode) old.parentNode.removeChild(old);
        }
      } catch {}
    });
    eventSource.addEventListener('log', e => {
      try {
        const entry = JSON.parse(e.data);
        const container = $('#log-list');
        if (!container || logPaused) return;
        const row = renderLogRow(entry);
        container.appendChild(row);
        logLines.push(row);
        while (logLines.length > LOG_MAX) {
          const old = logLines.shift();
          if (old.parentNode) old.parentNode.removeChild(old);
        }
        if (logLines.length > 10) container.scrollTop = container.scrollHeight;
        throttledRefresh();
      } catch {}
    });
    eventSource.addEventListener('node', () => throttledRefresh());
    eventSource.addEventListener('cache', () => throttledRefresh());
    eventSource.addEventListener('crash', () => throttledRefresh());
    eventSource.addEventListener('rebase_progress', e => {
      try {
        const d = JSON.parse(e.data);
        const results = $('#rebase-results');
        if (!results) return;
        const cls = d.status === 'upgraded' ? 'rb-upgraded'
          : d.status === 'same' ? 'rb-same'
          : (d.status === 'failed' || d.status === 'error') ? 'rb-failed'
          : d.status === 'trying' ? 'rb-already'
          : 'rb-already';
        const text = d.status === 'trying'
          ? `${d.song || '?'} - ${d.artist || '?'} | trying... | ${d.message || ''}`
          : `${d.song || '?'} - ${d.artist || '?'} | tier: ${d.from_tier || '?'} -> ${d.to_tier || '?'} | ${d.source || ''}`;
        results.appendChild(el('div', {class: `rebase-row ${cls}`}, text));
        const summary = $('#rebase-summary');
        if (summary && d.total) summary.textContent = `${d.done}/${d.total} upgraded=${d.upgraded||0} same=${d.same||0} failed=${d.failed||0}`;
        results.scrollTop = results.scrollHeight;
      } catch {}
    });
    eventSource.addEventListener('probe_progress', e => {
      try {
        const d = JSON.parse(e.data);
        // Servers older than the run_id echo send no run_id; accept those
        // rather than dropping every line silently (empty #refetch-live) --
        // but never render into an idle run with no active probe.
        if (d.run_id && d.run_id !== probeRunId) return;
        if (!d.run_id && !probeRunId) return;
        const final = !d.provider || d.provider === 'probe';
        if ((d.status === 'done' || d.status === 'complete') && final) { finishProbeRun(); return; }
        if (d.status === 'error' && final) { finishProbeRun(true); return; }
        if (d.status === 'found' && d.run_id) {
          probeFoundCount++;
          setProbeStatus(`probing... ${probeFoundCount}`, 'pill-warn');
        }
        probeLiveLine(d.provider || '?', d.status || '', d.detail || '');
      } catch {}
    });
    eventSource.addEventListener('retitle_progress', e => {      try {
        const d = JSON.parse(e.data);
        const results = $('#retitle-results');
        if (!results) return;
        const isOk = d.status === 'retitled_and_cached';
        const cls = isOk ? 'rb-upgraded' : d.status === 'retitled_no_lyrics' ? 'rb-failed' : d.status === 'retitling' || d.status === 'fetching' ? 'rb-already' : 'rb-same';
        const oldText = `${d.song || '?'} - ${d.artist || '?'}`;
        const newText = d.new_title ? `${d.new_title} - ${d.new_artist || '?'}` : '';
        let text;
        if (d.status === 'retitling' || d.status === 'fetching') {
          text = `${oldText} | ${d.message || d.status}...`;
        } else {
          text = `old: ${oldText}`;
          if (newText) text += `\nnew: ${newText}`;
          text += `\n${d.status} | ${d.source || ''}`;
        }
        const row = el('div', {class: `rebase-row ${cls}`, style: (d.status !== 'retitling' && d.status !== 'fetching') ? 'display:flex; flex-direction:column; gap:2px;' : ''},
          d.status !== 'retitling' && d.status !== 'fetching'
            ? [el('span', {style:'font-size:11px; opacity:.6;'}, `old: ${oldText}`), el('span', {style:'font-weight:600;'}, newText ? `new: ${newText}` : ''), el('span', {style:'font-size:11px; opacity:.6;'}, `${d.status} | ${d.source || ''}`)]
            : text
        );
        results.appendChild(row);
        const summary = $('#retitle-summary');
        if (summary && d.total) summary.textContent = `${d.done}/${d.total}`;
        results.scrollTop = results.scrollHeight;
      } catch {}
    });
    eventSource.addEventListener('rebase', e => { if (activePage === 'library') loadLibrary(); });
    eventSource.addEventListener('retitle', e => { if (activePage === 'library') loadLibrary(); });
    eventSource.addEventListener('jwt', () => { if (activePage === 'jwt') loadJwt(); });
    eventSource.addEventListener('ping', () => {
      // Server-driven refresh cadence (see ?interval=): no client polling.
      throttledRefresh();
      if (activePage === 'overview') loadOverview();
      if (activePage === 'jwt') loadJwt();
    });
    eventSource.addEventListener('bulk_progress', e => {
      try {
        const d = JSON.parse(e.data);
        if (!d.job_id || d.job_id !== bulkJobId || !bulkState) return;
        if (d.type === 'start') {
          bulkState.current = {video_id: d.video_id, song: d.song, artist: d.artist};
          bulkState.stage = '';
        } else if (d.type === 'stage') {
          bulkState.stage = `${d.song || d.video_id || '?'} | trying ${d.provider || '?'}...`;
        } else if (d.type === 'row' && d.row) {
          bulkState.results.push(d.row);
          while (bulkState.results.length > 300) bulkState.results.shift();
          bulkState.done = d.done != null ? d.done : bulkState.done;
          if (d.upgraded != null) bulkState.upgraded = d.upgraded;
          if (d.kept != null) bulkState.kept = d.kept;
          if (d.failed != null) bulkState.failed = d.failed;
          if (d.errors != null) bulkState.errors = d.errors;
          if (d.tq_done != null) bulkState.tq_done = d.tq_done;
          if (d.tq_queued != null) bulkState.tq_queued = d.tq_queued;
          bulkState.stage = '';
        } else if (d.type === 'done') {
          bulkState.state = d.state || 'done';
          bulkState.current = null;
          bulkState.stage = '';
        }
        renderBulk(bulkState);
        if (d.type === 'done') { try { sessionStorage.removeItem('ymtu-bulk-job'); } catch {} loadCaches(); loadLibrary(); }
      } catch {}
    });
    eventSource.addEventListener('playlist_sync_progress', e => {
      try {
        const d = JSON.parse(e.data);
        if (!d.job_id || d.job_id !== plJobId || !plState) return;
        if (d.state === 'complete' || d.state === 'stopped' || d.state === 'failed') {
          plState.state = d.state;
          renderPlSync(plState);
          try { sessionStorage.removeItem('ymtu-playlist-job'); } catch {}
          loadCaches();
          loadLibrary();
          return;
        }
        if (d.video_id) {
          const t = {video_id: d.video_id, title: d.song, song: d.song, artist: d.artist,
                     tag: d.status, status: d.status, source: d.source || ''};
          const ix = plState.tracks.findIndex(x => x.video_id === d.video_id);
          if (ix >= 0) plState.tracks[ix] = t; else plState.tracks.push(t);
          plState.done = d.done != null ? d.done : plState.done;
          plState.total = d.total != null ? d.total : plState.total;
          plState.found = plState.tracks.filter(x => (x.tag || x.status) === 'found').length;
          plState.unlyriced = plState.tracks.filter(x => (x.tag || x.status) === 'unlyriced').length;
          plState.error_count = plState.tracks.filter(x => { const s = x.tag || x.status; return s === 'error' || s === 'invalid_id'; }).length;
          plState.current = `${d.song || d.video_id || ''} - ${d.artist || ''}`;
          renderPlSync(plState);
        }
      } catch {}
    });
    eventSource.addEventListener('open', () => {
      const dot = $('#log-conn');
      if (dot) { dot.innerHTML = '<span class="live-dot"></span> connected'; dot.className = 'pill pill-ok'; }
    });
    eventSource.addEventListener('error', () => {
      const dot = $('#log-conn');
      if (dot) { dot.innerHTML = 'reconnecting...'; dot.className = 'pill pill-warn'; }
    });
  };
  const throttledRefresh = mdui.throttle(() => {
    if (activePage === 'caches') loadCaches();
    if (activePage === 'library') loadLibrary();
    if (activePage === 'nodes') loadNodes();
    if (activePage === 'crashes') loadCrashes();
  }, 2000);

  const downloadLogs = () => { window.open('/api/admin/logs/download', '_blank'); };
  const clearLogs = async () => {
